import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Costruzioni geometriche con riga e compasso","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fl/fl.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fl/fl.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fl/fl.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="costruzioni-geometriche-con-riga-e-compasso" tabindex="-1">Costruzioni geometriche con riga e compasso <a class="header-anchor" href="#costruzioni-geometriche-con-riga-e-compasso" aria-label="Permalink to “Costruzioni geometriche con riga e compasso”">​</a></h1><p>È un argomento ormai obsoleto, secondo me.</p><p>Si rifà a un tempo dove era importante costruire con riga e compasso: il costruire con riga e compasso equivale in algebra a risolvere problemi utilizzando equazioni di primo grado o in aritmetica ad usare solamente numeri razionali.</p><p>Quando andavo all&#39;Università (temporibus illis) ancora c&#39;erano (o almeno sembrava ci fossero) differenze &quot;sociali&quot; fra i vari professori: il top erano i professori di geometria, seguivano i professori di algebra e quindi analisi mentre erano considerati piuttosto in sott&#39;ordine i professori di matematica applicata. Questo purtroppo è stato uno dei motivi per cui mi sono rifiutato di scegliere matematica applicata (informatica) all&#39;università, cosa che ancor oggi rimpiango.</p><p>Il massimo per i prof di geometria era proprio la geometria &quot;pura&quot; con riga e compasso; nella seconda stesura del sito dedicherò un capitolo alle costruzioni con riga (senza segni) e compasso; per ora questo argomento viene tralasciato.</p><ul><li class="text-red">[Primo argomento]</li><li class="text-red">[Secondo argomento]</li><li class="text-red">[Terzo argomento]</li></ul>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};